\begin{cor}\label{thm:type_I_inv}
                Let $A$ be a unital $C^*$-algebra of Type I. An element $a\in A$ is invertible if and only if for every irreducible representation $\pi$ of $A$, the implication
\[
\pi(a) \text{ is Fredholm } \;\Longrightarrow\; \pi(a) \text{ is invertible}
\]
holds.
        \end{cor}

