\begin{lemma}\label{lem:newtstructure}
Suppose that $F:\mathcal{K}_1\rightarrow \mathcal{K}_2$ is a full and dense triangulated functor between triangulated categories $\mathcal{K}_1, \mathcal{K}_2$. Let $\mathbbm{t}=(\mathcal{K}_1^{\leq 0}, \mathcal{K}_1^{\geq 0})$ be a $t$-structure on $\mathcal{K}_1$ and $\mathcal{U}, \mathcal{V}$ be the following full subcategories of $\mathcal{K}_2$:
\begin{eqnarray*}
&&\mathcal{U}:=\{X\in \mathcal{K}_2\mid \text{there exists some } X^\prime\in \mathcal{K}_1^{\leq 0} \text{ such that } F(X^\prime)\cong X\},\\
&&\mathcal{V}:=\{Y\in \mathcal{K}_2\mid \text{there exists some } Y^\prime\in \mathcal{K}_1^{\geq 0} \text{ such that } F(Y^\prime)\cong Y\}.
\end{eqnarray*}
Then $\tilde{\mathbbm{t}}:=(\mathcal{U}, \mathcal{V})$ is a $t$-structure on $\mathcal{K}_2$. In particular, if $\mathbbm{t}$ is bounded, then $\tilde{\mathbbm{t}}$ is also bounded.
\end{lemma}

