\label{thm:BBRiem}
Let $M$ be a smooth complete Riemannian manifold, $p\in(1,+\infty)$ and $(\mu_t)\subset \Prob_p(M)$ be a weakly continuous curve. Then:
\begin{itemize}
\item[\emph{(A)}]  Suppose that $(\mu_t)$ is $W_p$-absolutely continuous. Then there are vector fields $(v_t)$ so that
\begin{equation}
\label{eq:CE}\tag{CE}
\partial_t\mu_t+{\rm div}(v_t\mu_t)=0\quad\text{in the sense of distributions}
\end{equation}
and moreover
\[
|\dot\mu_t|\geq \|v_t\|_{L^p_{\mu_t}}\qquad a.e.\ t\in[0,1],
\]
where $|\dot\mu_t|:=\lim_{h\to 0}\frac{W_p(\mu_t,\mu_{t+h})}{h}$ (the a.e.\ existence of $|\dot\mu_t|$ follows from absolute continuity).
\item[\emph{(B)}] Suppose that $(v_t)$ is a family of vector fields so that \eqref{eq:CE} holds and $\int_0^1\|v_t\|_{L^p_{\mu_t}}\,\,\mathrm{d} t<+\infty$. Then $(\mu_t)$ is $W_p$-absolutely continuous and 
\[
|\dot\mu_t|\leq \|v_t\|_{L^p_{\mu_t}}\qquad a.e.\ t\in[0,1].
\]
\end{itemize}

ref_dict.Thm: main:
\begin{theorem} \label{Thm: main}
Let $(M,g)$ be a globally hyperbolic spacetime, $0 \neq p < 1$ and $(\mu_t)\subset  \Prob(M)$ be a causal path such that $\supp( \mu_t) \subset K$ for every $t \in [0,1]$, for some compact set $K\subset M$. Then:
\begin{itemize}
\item[\emph{(A)}] There exists a family of causal Borel vector fields $(v_t)$ such that $(\mu_t, v_t)$ satisfies  the causal continuity inequality and moreover
\begin{equation}
\int_0^1\tfrac1p |\dot \mu_t|_p ^p\,\d t \leq \int_0^1\tfrac1p \| v_t \|_{L^p_{\mu_t}} ^p\,\d t
\end{equation}
for almost every $t \in [0,1]$, where $|\dot\mu_t|_p = \lim_{h\downarrow0}\frac1h \ell_p(\mu_t,\mu_{t+h})$ (the a.e.\ existence of $|\dot\mu_t|_p$ follows from the causality of the curve -- see \cite[Theorem 2.23]{Octet}). 
\item[\emph{(B)}] For any family $(v_t)_{t \in [0,1]}$ of causal Borel vector fields  such that $\int_0^1 \tfrac1p \|v_t\|^p_{L^p_{\mu_t}} \, \d t >-\infty$ and  $(\mu_t, v_t)$ satisfies the causal continuity inequality we have 
\begin{equation} \label{eq: norm inequality}
\tfrac1p |\dot \mu_t|^p_p  \geq \tfrac1p   \| v_t \|^p_{L^p_{\mu_t}}  \qquad a.e.\ t.
\end{equation}
\end{itemize}
\end{theorem}

ref_dict.thm: BB theorem Lor:
\begin{theorem}[Benamou--Brenier formula for spacetimes]
\label{thm: BB theorem Lor} 
Let $(M,g)$ be a globally hyperbolic spacetime and let $0 \neq p <1$. 
Let $\overline{\mu}_0, \overline{\mu}_1 \in \Prob(M)$ be two probability measures with compact support. 
Then
\begin{equation} 
\label{eq: BB formula}
u_p(\ell_p(\overline{\mu}_0, \overline{\mu}_1)) = \sup \int_0^1 \int u_p(\|v_t(x) \|_g) \, \d \mu_t(x) \, \d t \, ,
\end{equation}
where the supremum is taken over all solutions $(\mu_t,v_t)$ of the causal continuity inequality such that  $\overline{\mu}_0 \preceq \mu_t \preceq \overline{\mu}_1$ for every $t\in[0,1]$.
 Moreover, if $\overline{\mu}_0 \preceq \overline{\mu}_1$ then the supremum on the right hand side of \eqref{eq: BB formula}
is achieved.
\end{theorem}

