ref_dict.thm:conv:
\begin{mainthm}\label{thm:conv}
		Let f be a biholomorphism of form \eqref{eq:f} and such that for all $i \in \{1, \ldots, n\}$, we have $\Ree \left(\frac{a_i}{\aM} \right) > 0$. Then in any neighbourhood of the origin there exists $d$ pairwise disjoint connected open sets $\Omega^{+}_0, \ldots, \Omega^{+}_{d-1}$ with $0 \in \partial \Omega^+_k$ for all $k$ and  $d$ pairwise disjoint connected open sets $\Omega^{-}_0, \ldots, \Omega^{-}_{d-1}$ with $0 \in \partial \Omega^-_k$ for all $k$, such that the following assertions hold:
		\begin{enumerate}
			\item The sets $\Omega^+_k$ are invariant by $f$ and $f^{\circ j} \to 0$ as $j \to +\infty$ compactly on $\Omega^+_k$ for all k, and the sets $\Omega^-_k$ are invariant by $f^{-1}$ and $f^{\circ -j} \to 0$ as $j \to +\infty$ compactly on $\Omega^-_k$ for all k.
			\item The sets $\Omega^{+}_0, \ldots, \Omega^{+}_{d-1}, \Omega^{-}_0, \ldots, \Omega^{-}_{d-1}$ together with the fixed set $\{\x^M = 0\}$ form a neighbourhood of the origin.
			\item For each $k$, there exists biholomorphisms $\phi^+_k : \Omega^+_k \to W^+_k \in \CC^n$ and $\phi^-_k : \Omega^-_k \to W^-_k \in \CC^n$ with the following properties :
			\begin{itemize}
				\item $\phi^+_k$ and $\phi^-_k$ conjugate $f$ to $(z, w_1, \ldots, w_{n-1}) \to (z+1, w_1, \ldots, w_{n-1})$,
				\item the sets $W^+_k$ and $W^-_k$ satisfy:
				$$
				\bigcup_{\pm j \in \NN} T_j \left(W^{\pm}_k \right)= \CC \times (\CC^*)^{n-\bar{m}-1} \times \CC^{\bar{m}}.
				$$
			\end{itemize}
		\end{enumerate}
	\end{mainthm}

ref_dict.prop:psi_I:
\begin{prop}\label{prop:psi_I}
		The sequence $\left(g_I (f^{\circ j} (\x))\right)_j$ converges uniformly on $U_0$ to a holomorphic function $\psi_I$ invariant by $f$. Moreover there exists $u_I$ holomorphic such that $\psi_I = g_I u_I$ and $u_I - 1 = O (\abs{\x^m}^{\gamma})$.
	\end{prop}

ref_dict.thm:div:
\begin{mainthm}\label{thm:div}
		Let f be a biholomorphism of form \eqref{eq:f} such that there exists $i \in \{1, \ldots, n\}$ such that $\Ree \left(\frac{a_i}{\aM} \right) < 0$.
		Then there exists a neighbourhood $U$ of the origin such that for any $p \in U$ outside of the fixed point set, there exists $j \in \NN$ such that $f^{\circ j} (p) \notin U$ and $j' \in \NN$ such that $f^{\circ -j'} (p) \notin U$.
	\end{mainthm}

