	If $X$ is a formal prestack, there is an equivalence:
	\[\Pois(X,n) \simeq \Lag\Thick(X,n+1).\]
\end{thm}

ref_dict.thm:aksz:
\begin{thm}\label{thm:aksz}
	Let $X$ be an $n$-shifted derived Poisson formal prestack and $Y$ a $d$-oriented prestack. Assume, moreover, that $\MapSt(Y,X)$ is locally of finite presentation; then
	\[\MapSt(Y,X)\]
	has a natural $(n-d)$-shifted Poisson structure.
\end{thm}

