\end{align}

ref_dict.thm: quantitative Mitchell:
\begin{thm}\label{thm: quantitative Mitchell}
 Let $G$ be a sub-Finsler Lie group. With respect to a tangent grading, consider the tangent metric $d_0$ on $G$ and the dilated metrics $d_\epsilon$. Then, there are a neighborhood $\Omega$ of $1$ in $G$ and $C>0$ such that 
 \begin{align}\label{thm: eq: quantitative mitchell0}
     -Cd_\epsilon(p,q)^{1/\beta}\epsilon^{\alpha_0/\beta}&\leq d_\epsilon(p,q)-d_0(p,q)
     \leq Cd_0(p,q)^{1/\beta}\epsilon^{\alpha_0/\beta}, \quad \forall \epsilon \in [0,1], \; \forall p,q \in \Omega,
 \end{align}
  where $\alpha_{0}$ and $\beta$ are the constants from Definition~\ref{def: constant alpha mitchell} and~\ref{def: constant beta}.
\end{thm}

ref_dict.main thm: pansu:
\begin{thm}[Quantitative Pansu]\label{main thm: pansu}
 Let $(G,d)$ be a geodesic Lie group. Assume $G$ is simply connected and nilpotent.
 After fixing an asymptotic grading, consider the associated Pansu limit metric $d_\infty$ on $G$ and the constants $\alpha_\infty$ and $\beta$ defined in \eqref{def_alpha_inf} and \eqref{def_beta}, respectively. Then, for some $C>0$, we have 
 \begin{align}\label{eq: main pansu1}
  \left|d(p,q)-d_\infty(p,q)\right| \leq C\max\left\{d_\infty(1,p),d_\infty(1,q)\right\}^{1-\alpha_\infty/\beta}, \quad \forall p\in G, \;\forall q \in G \setminus B_{d_\infty}(1,1).
 \end{align}
\end{thm}

ref_dict.thm: Mitchell tangent thm:
\begin{thm}[Mitchell Tangent Theorem]\label{thm: Mitchell tangent thm}
 Let $(G,d)$ be a sub-Finsler Lie group and $p \in G$. Then the tangent cone of $G$ at $p$ is the osculating Carnot group $(G_0,d_0).$
\end{thm}

ref_dict.thm: Pansu asymptotic thm:
\begin{thm}[Pansu Asymptotic Theorem \cite{Pan83}]\label{thm: Pansu asymptotic thm}
 The asymptotic cone of a simply connected nilpotent sub-Finsler Lie group $(G,d)$ is the Carnot group $(G_\infty,d_\infty).$
\end{thm}

expanded_sketch:
We briefly summarize the strategy to obtain the theorems, focusing on establishing the main theorem. One considers “a one-parameter family of Lie group products $(*_\epsilon)_{\epsilon\in \mathbb{R}}$ on $G$ such that $G=(G,*_1)$ and $(G,*_0)$ is isomorphic to the asymptotic cone of $G$,” and introduces “a one-parameter family of geodesic metrics $(\rho_\epsilon)_{\epsilon\in \mathbb{R}}$ on $G$ such that $\rho_\epsilon$ is $*_\epsilon$-left-invariant for every $\epsilon$, $\rho_1=d$, and $\rho_0=d_\infty$.”

In establishing the main theorem, one deduces it from the following quantitative convergence statement.
\begin{thm}\label{thm: quantitative Pansu}
 Let $G$ be a simply connected nilpotent sub-Finsler Lie group. With respect to an asymptotic grading, consider the Pansu limit metric $\rho_0$ on $G$ and the contracted metrics $\rho_\epsilon$. Then, for every compact set $K \subseteq G$, there is a constant $C>0$ such that
 \begin{equation}\label{eq: thm: quantitative pansu}
  \left|\rho_0(p,q)-\rho_\epsilon(p,q)\right| \leq C \epsilon^{\alpha_{\infty}/\beta}, \quad \forall \epsilon \in [0,1], \; \forall p,q \in K,
 \end{equation}
  where $\alpha_{\infty}$ and $\beta$ are the constants from Definition~\ref{def: constant alpha pansu} and~\ref{def: constant beta}.
\end{thm}

To prove (for fixed compact $K$) “$\rho_0(p,q)-\rho_\epsilon(p,q)\lesssim \epsilon^{\alpha_\infty/\beta}$,” one starts “with a $\rho_\epsilon$-geodesic $\gamma$ from $p$ to $q$,” constructs “a curve $\gamma_0$ such that $\gamma_0(0)=p$ and $\mathrm{Length}_{\rho_0}(\gamma_0)\le \mathrm{Length}_{\rho_\epsilon}(\gamma)$,” and then “bound[s] the $\rho_0$-distance of the endpoints of $\gamma$ and $\gamma_0$.” For that endpoint bound, one uses that “for every Carnot quotient ideal $\mathfrak{i}\triangleleft \mathrm{Lie}(G)$ and for every $\epsilon\in[0,1]$, the curve $t\mapsto \gamma_\epsilon^{-1}(t)*_\epsilon\gamma(t)$ lies in $\mathfrak{i}$,” and then applies “the Ball-Box Theorem and the definition of $\beta$, as well as a Grönwall-type lemma and the definition of $\alpha_\infty$,” to control the $\rho_0$-distance between the endpoints of $\gamma$ and $\gamma_0$. The reverse inequality is proved “using the same techniques.”

expanded_theorem:
[Quantitative Pansu]\label{main thm: pansu}
 Let $(G,d)$ be a geodesic Lie group. Assume $G$ is simply connected and nilpotent.
 After fixing an asymptotic grading, consider the associated Pansu limit metric $d_\infty$ on $G$ and the constants $\alpha_\infty$ and $\beta$ defined as follows:
 \begin{eqnarray}\nonumber
   \alpha_{\infty}&\coloneqq & \alpha_{\infty}(\Delta, (V_i)_i) \\\nonumber
   &\coloneqq &\min\{\alpha_{(1,\infty)}, \alpha_{(2,\infty)}\}
   \\\label{def_alpha_inf}
   &=& 
   \max \left\{j \in \mathbb{N} \, : 
   \begin{cases}
    k \in \mathbb{N}, \; p \in \mathbb{N}^k, \;\\ v \in \Delta \end{cases}\implies \begin{cases}
     [V_{p_1},\ldots,V_{p_k}] \subseteq V_{|p|} \oplus V_{\geq |p|+j}, \,\\
   \, v-\pi_1(v) \in \mathfrak{g}^{(j+1)} 
   \end{cases}\right\}
   .
\end{eqnarray}
 and
 \begin{equation}\label{def_beta}
 \beta:=\beta(\Delta,(D_i)_i):= \min\{k\in \mathbb Z\,:\, \exists \mathfrak{i} \subseteq D_{\leq k} \, \text{Carnot quotient ideal}
 \}.
\end{equation}
 Then, for some $C>0$, we have 
 \begin{align}\label{eq: main pansu1}
  \left|d(p,q)-d_\infty(p,q)\right| \leq C\max\left\{d_\infty(1,p),d_\infty(1,q)\right\}^{1-\alpha_\infty/\beta}, \quad \forall p\in G, \;\forall q \in G \setminus B_{d_\infty}(1,1).
 \end{align}

