S(s) \leq K_S (1+s)^{q}, \quad  s \geq 0
\end{align}
with some $K_D,K_S > 0$ and $p,q\in \mathbb{R}$ fulfilling
\begin{align*}
q-p<2-\frac{n}{2} .
\end{align*}
Then, for all initial data fulfilling $(\ref{eq1.1})$, the solution of (\ref{eq1.1.0}) exists globally and remains bounded in the sense that there exists $C>0$ independent of $t$ such that
