ref_dict.thm:heinz-Etau:
\begin{thm}[Heinz-type inequality in $\Etau$, {\cite[Corollary~5.8(i)]{DDSZ20}}]\label{thm:heinz-Etau}
		Let $a,b\ge 0$ in $\Stau$ and $z\in \Stau$. If $az,zb\in \Etau$, then for every $t\in[0,1]$,
		\[
		\norm{a^t z b^{1-t}+a^{1-t} z b^t}_{\Etau}\le \norm{az+zb}_{\Etau}.
		\]
	\end{thm}

ref_dict.thm:Liu_He_Zhao:
\begin{thm}\label{thm:Liu_He_Zhao}
		Let $a,b\ge 0$ in $\Etau$ and $t\in[0,1/4]\cup [3/4,1]$. Then
		\begin{equation*}
			\norm{a^t b^{1-t}+b^t a^{1-t}}_{\Etau}
			\le
			2^{2\abs{t-1/2}-1/2}\;\norm{a+b}_{\Etau}.
		\end{equation*}
	\end{thm}

ref_dict.thm:main:
\begin{thm}[Bourin-type bound in $\Etau$]\label{thm:main}
		Let $a,b\ge 0$ in $\Etau$ and $t\in[0,1]$. Then
		\begin{equation}\label{eq:main}
			\norm{a^t b^{1-t}+b^t a^{1-t}}_{\Etau}
			\le
			2^{\max\{\,2\abs{t-1/2}-1/2,\;0\,\}}\;\norm{a+b}_{\Etau}.
		\end{equation}
		In particular, if $t\in[1/4,3/4]$, then
		\[
		\norm{a^t b^{1-t}+b^t a^{1-t}}_{\Etau}\le \norm{a+b}_{\Etau}.
		\]
	\end{thm}

