In particular, if $a,b\in E(\tau)$, then taking $z=1$ in Theorem~\ref{thm:heinz-Etau} yields the usual Heinz inequality in $E(\tau)$:
	\[
	\norm{a^tb^{1-t}+a^{1-t}b^t}_{E(\tau)}\le \left\lVert a+b\right\rVert_{E(\tau)}, \qquad t\in [0,1].
	\]

	In this paper, we focus on Bourin's crossed Heinz expression for $\tau$-measurable operators in fully symmetric spaces.
	Liu, He and Zhao \cite{LHZ26}  proved the following bound for $t\in[0,1/4]\cup[3/4,1]$.
	\begin{thm}\label{thm:Liu_He_Zhao}
		Let $a,b\ge 0$ in $E(\tau)$ and $t\in[0,1/4]\cup [3/4,1]$. Then
		\begin{equation*}
			\norm{a^t b^{1-t}+b^t a^{1-t}}_{E(\tau)}
			\le
			2^{2\left\lvert t-1/2\right\rvert-1/2}\;\left\lVert a+b\right\rVert_{E(\tau)}.
		\end{equation*}
	\end{thm}
	By using a complex interpolation argument based on the three-lines theorem on a strip, we prove that the optimal constant $1$ holds on the full central range $t\in[1/4,3/4]$ and obtain an explicit bound valid for all $t\in[0,1]$, which generalizes  Kittaneh--Ricard's result~\eqref{eq:KR-bound} and Theorem~\ref{thm:Liu_He_Zhao}.
	\begin{thm}[Bourin-type bound in $E(\tau)$]\label{thm:main}
		Let $a,b\ge 0$ in $E(\tau)$ and $t\in[0,1]$. Then
		\begin{equation}\label{eq:main}
			\norm{a^t b^{1-t}+b^t a^{1-t}}_{E(\tau)}
			\le
			2^{\max\{\,2\left\lvert t-1/2\right\rvert-1/2,\;0\,\}}\;\left\lVert a+b\right\rVert_{E(\tau)}.
		\end{equation}
		In particular, if $t\in[1/4,3/4]$, then
		\[
		\norm{a^t b^{1-t}+b^t a^{1-t}}_{E(\tau)}\le \left\lVert a+b\right\rVert_{E(\tau)}.
		\]
	\end{thm}

	\medskip

	\noindent\textbf{Organization of this paper.}
	Section~\ref{sec:prelim} recalls the notation for $\tau$-measurable operators and fully symmetric spaces $E(\tau)$.
	It also collects several tools used later, including a H\"older-type inequality, the three-lines lemma on a strip,
	an arithmetic--geometric mean inequality, an Araki--Lieb--Thirring-type (ALT-type) submajorization statement, and a Douglas-type factorization lemma.
	Section~\ref{sec:bourin} establishes a complex interpolation estimate for an auxiliary expression $f_t$,
	then proves a bridge inequality via a $2\times2$ block-positivity argument, and finally combines these ingredients to prove
	Theorem~\ref{thm:main}.

ref_dict.lem:Sr-trunc:
\begin{lemma}[Safe $p^6$-truncations for $p\ge 7$ and $r\le p$]\label{lem:Sr-trunc}
Let $p\ge 7$ be prime and write $S_r=S_r(p-1)=\sum_{t=1}^{p-1}t^r$ with $r\le p$.
Then in $\ZZ_{(p)}$:
\begin{enumerate}
\item If $r\ge 6$ is even, then
\begin{equation}\label{eq:Sr-even}
S_r \equiv
pB_r+\frac{p^3}{3!}\,r(r-1)B_{r-2}+\frac{p^5}{5!}\,r(r-1)(r-2)(r-3)B_{r-4}
\pmod{p^6}.
\end{equation}
For $r\in\{2,4\}$ the same congruence holds after adding the extra term $p^rB_1$.
\item If $r\ge 7$ is odd, then
\begin{equation}\label{eq:Sr-odd}
S_r \equiv
\frac{p^2}{2!}\,r\,B_{r-1}+\frac{p^4}{4!}\,r(r-1)(r-2)B_{r-3}
\pmod{p^6}.
\end{equation}
For $r\in\{3,5\}$ the same congruence holds after adding the extra term $p^rB_1$.
\item For $r=1$ we have the exact identity
\begin{equation}\label{eq:S1-exact}
S_1(p-1)=\frac{p(p-1)}{2}.
\end{equation}
\end{enumerate}
\end{lemma}

ref_dict.thm:modp:
\begin{theorem}[A mod \(p\) dichotomy for \(\G_n(p)\)]\label{thm:modp}
Let \(p\) be an odd prime.
\begin{enumerate}
\item If \((p-1)\nmid n\), then \(\G_n(p)\equiv 0\pmod p\) in \(\mathbb{Z}[\ii]\).
\item If \(n=r(p-1)\) with \(1\le r<p\), then
\[
\G_n(p)\equiv 1+\ii^{\,r(p-1)}\pmod p.
\]
In particular, \(\G_{p-1}(p)\equiv 0\pmod p\) if \(p\equiv 3\pmod 4\) and \(\G_{p-1}(p)\equiv 2\pmod p\)
if \(p\equiv 1\pmod 4\).
\end{enumerate}
\end{theorem}

ref_dict.conj:p3p5:
\begin{conjecture}[Closed formulas for $p=3$ and $p=5$]\label{conj:p3p5}
Let $p\in\{3,5\}$;
the computed data for $1\le n\le 2000$ suggest the following explicit formulas for all $n\ge 1$.

\begin{enumerate}
\item\label{it:p3} \textup{($p=3$).} For every $n\ge 1$,
\[
v_3(\G_n(3))=
\begin{cases}
0, & 4\mid n,\\[1mm]
1+v_3(n), & n\equiv 1\pmod 4,\\[1mm]
2+v_3(n)+v_3(n-1), & n\equiv 2\pmod 4,\\[1mm]
2+v_3(n)+v_3(n-1)+v_3(n-2), & n\equiv 3\pmod 4.
\end{cases}
\]

\item\label{it:p5} \textup{($p=5$).} For every $n\ge 1$,
\[
v_5(\G_n(5))=
\begin{cases}
0, & 4\mid n,\\[1mm]
1+v_5(n), & n\equiv 1\pmod 4,\\[1mm]
2+v_5(n)+v_5(n-1), & n\equiv 2\pmod 4,\\[1mm]
3+v_5(n)+v_5(n-1)+v_5(n-2), & n\equiv 3\pmod 4.
\end{cases}
\]
Equivalently, if $r\in\{1,2,3\}$ and $n\equiv r\pmod 4$, then
\[
v_5(\G_n(5))=r+\sum_{j=0}^{r-1} v_5(n-j).
\]
\end{enumerate}
\end{conjecture}

ref_dict.cor:location:
\begin{corollary}[Exact location in the complex plane]\label{cor:location}
Write $\G_n(N)=x+y\ii$ with $x,y\in\ZZ$. Then:
\[
\begin{array}{rcl}
n\equiv 0\ (\mathrm{mod}\ 4) &\Rightarrow& y=0 \quad (\text{$\G_n(N)$ is real}),\\
n\equiv 2\ (\mathrm{mod}\ 4) &\Rightarrow& x=0 \quad (\text{$\G_n(N)$ is purely imaginary}),\\
n\equiv 1\ (\mathrm{mod}\ 4) &\Rightarrow& x=y,\\
n\equiv 3\ (\mathrm{mod}\ 4) &\Rightarrow& x=-y.
\end{array}
\]
\end{corollary}

