\label{NCMinA}
    Let $(\mathcal{M},\tr)$ be a tracial von Neumann algebra,  $\mathcal{N}\subset \mathcal{L},\mathcal{K}\subset \mathcal{M}$ be von Neumann subalgebras and $x\in \mathcal{M}$ be a positive element satisfying the following:
    \begin{enumerate}
        \item Either $\mathcal{L}$ and $\mathcal{K}$ commute, or $x$ is in the center of $\mathcal{M}$;\label{variants}
        \item The quadrilateral inclusion $$
    \begin{tikzcd}
        \mathcal{L}\arrow[r,symbol=\subset, "E_\mathcal{L}" {yshift=3pt}] & \mathcal{M}\\
        \mathcal{N}\arrow[r,symbol=\subset,"E_\mathcal{N}"'{yshift=-3pt}] \arrow[u,symbol=\subset,"E_\mathcal{N}"{xshift=-3pt}] & \mathcal{K}\arrow[u,symbol=\subset, "E_\mathcal{K}"' {xshift=3pt}]
    \end{tikzcd}
    $$
    is a commuting square where $E_\mathcal{L}$, $E_\mathcal{K}$, and $E_\mathcal{N}$ are the unique $\tr$-preserving conditional expectations.
    \end{enumerate}
    Then for $1\le p<\infty$ we have
    \begin{equation*}
        E_\mathcal{L}(E_{\mathcal{K}}(x)^p)^{1/p}\le E_{\mathcal{K}}(E_\mathcal{L}(x^p)^{1/p}).
    \end{equation*}

ref_dict.Holderlike:
\begin{lem}[Reduced H\"older inequality]\label{Holderlike}
    Let $x,y\in \M_+$ and $q\in\M$ be a projection. For $1< p< \infty$
    \begin{equation}
        \tr(qxq y)\le \tr(qx^pq)^{1/p}\tr(qy^{p'}q)^{1/p'}.\label{Holderlikeineq}
    \end{equation}
    If $x$ and $y$ are nonzero and have a spectral gap, then equality holds if and only if $[q,x]=0=[q,y]$ and $(xq)^p=\lambda (yq)^{p'}$ for some $\lambda\in (0,\infty)$.
\end{lem}

ref_dict.fusion ringA:
\begin{coralpha}\label{fusion ringA}
    Let $\mathcal{C}$ be a spherical unitary (multi-)tensor category with $s$ isomorphism classes of simple objects where $s\in \mathbb{N}\cup\{\infty\}$. Suppose that the simple objects $c_i\in \Irr(\mathcal{C})$ satisfy the fusion rules $c_i\otimes c_j\cong \bigoplus_{l=1}^s N_{ij}^l c_l$ and let $d_i$ be the quantum dimension of $c_i$. Then for any triple of simple objects $c_i,c_j,c_k\in\Irr(\mathcal{C})$, $1\le p<\infty$, and $a_n\ge0$ for $1\le n\le s$, we have
    \begin{equation*}
        \left(\sum_{l=1}^{s}\left(\sum_{n=1}^{s} \frac{N_{lk}^n\ a_nd_n}{d_l}\right)^p \frac{N_{ij}^ld_l}{d_j}\right)^{\frac{1}{p}} \le \sum_{m=1}^{s}\left(\sum_{n=1}^{s}  \frac{N_{im}^n\ a_n^pd_n}{d_m}\right)^{\frac{1}{p}}\frac{N_{jk}^m d_m}{d_j}.
    \end{equation*}
\end{coralpha}

