ref_dict.monotonicity-J:
\begin{prop}\label{monotonicity-J}
  For all $\gamma \in \Jb^{>0}$, the map $x \mapsto \gamma \circ x$ is strictly increasing.
\end{prop}

ref_dict.monotonicity:
\begin{mainthm}[Monotonicity]\label{monotonicity}
    For all $f \in \OM$, the function $x \mapsto f \circ x$ for $x \in \Ub^{>\Rb}$ is strictly increasing if $f' > 0$, strictly decreasing if $f' < 0$, and constant if $f' = 0$.
\end{mainthm}

ref_dict.taylor:
\begin{mainthm}[Taylor approximation for $\OM$]\label{taylor}
    Let $f \in \OM$ with $f \not\asymp T^k$ for any $k \in \Nb$, and let $x,\delta \in \Ub$ with $x > \Rb$ and $\delta \prec x$, $\frac{f' \circ x}{f \circ x}\delta \prec 1$. Then for all $n \geq 0$,
    \[ f \circ (x + \delta) = \sum_{i = 0}^n \frac{f^{(i)} \circ x}{i!}\delta^i + O\left((f^{(n+1)} \circ x)\delta^{n+1}\right). \]
\end{mainthm}

ref_dict.weak-mvp:
\begin{lem}\label{weak-mvp}
  For all $\gamma \in \Jb^{>0}$ and all $x, y \in \Ub$ with $x > y > \Rb$, we have:
  \begin{enumerate}
      \item\label{weak-mvp-small} if $\gamma \circ x - \gamma \circ y \preceq 1$, then $\frac{\gamma \circ x - \gamma \circ y}{x - y} \preceq \gamma' \circ y$,
      \item\label{weak-mvp-large} if $\gamma \circ x - \gamma \circ y \succeq 1$, then $(\gamma' \circ y)(x - y) \succeq 1$.
  \end{enumerate}
\end{lem}

ref_dict.radius-of-convergence:
\begin{cor}\label{radius-of-convergence}
    For all $f \in \OM$, if $f \not\asymp T^k$ for any $k \in \Nb$, then eventually the sequence $(f^{(k)} \circ x)\delta^{k}$ is strictly $\prec$-decreasing when $\delta \prec x$ and $(f^\dagger \circ x)\delta \prec 1$, and weakly $\prec$-increasing otherwise.
\end{cor}

expanded_sketch:
A naive approach to prove the main theorem is described as an induction on the construction of $\Rb\wspc{T}$ from $T$: the conclusion is checked in the base cases $f=T,\ f=\log(T),\ldots$, and for a general sum $f=\sum_{i<\alpha} r_i e^{\gamma_i}$ one “assume[s] the conclusion for each map $x\mapsto \gamma_i\circ x$” and then wants to deduce monotonicity of $x\mapsto f\circ x$.

This induction “works very well for $f\in\Jb_\mathfrak{O}^{>0}$”. We first prove the following proposition.
\begin{prop}\label{monotonicity-J}
  For all $\gamma \in \Jb^{>0}$, the map $x \mapsto \gamma \circ x$ is strictly increasing.
\end{prop}
But it “falls short for the general case,” so an extra ingredient is introduced: a “very weak form of mean value property.” For $\gamma\in\Jb_\mathfrak{O}^{>0}$ and $x>y>\mathbb{R}$ it gives the estimate
\[
\frac{\gamma\circ x-\gamma\circ y}{x-y}\preceq \gamma'\circ y\quad\text{at least when}\quad \gamma\circ x-\gamma\circ y\preceq 1\ \text{or}\ (\gamma'\circ y)(x-y)\prec 1.
\]
This condition is said to be “almost trivial to verify” in the base cases $T,\log(T),\ldots$ because the functions $x\mapsto \log^{\circ n}(x)$ are “strictly increasing and \emph{concave}.”

With this weak mean value property in hand, “the rest of the induction is then relatively straightforward.” We first prove the following lemma.
\begin{lem}\label{weak-mvp}
  For all $\gamma \in \Jb^{>0}$ and all $x, y \in \Ub$ with $x > y > \Rb$, we have:
  \begin{enumerate}
      \item\label{weak-mvp-small} if $\gamma \circ x - \gamma \circ y \preceq 1$, then $\frac{\gamma \circ x - \gamma \circ y}{x - y} \preceq \gamma' \circ y$,
      \item\label{weak-mvp-large} if $\gamma \circ x - \gamma \circ y \succeq 1$, then $(\gamma' \circ y)(x - y) \succeq 1$.
  \end{enumerate}
\end{lem}
Using this auxiliary lemma, the induction leads to a fairly short proof, thereby establishing the main theorem.

theorem.content:
\label{thm: simplicial + T(6) implies CAT(0)}
    Let $G=\langle f: \Gamma \rightarrow \Theta\rangle$ be a $T(q)$ graphical small cancellation presentation with $Girth(\Gamma)\geq p$, where $Girth(\Gamma)$ denotes the length of a shortest cycle in $\Gamma$, and let $X$ be the non-thickened graphical complex associated to this presentation. 
    \begin{enumerate}[label=(\arabic*)]
        \item If $(p,q)=(3,6)$, then $X$ admits a locally CAT(0) metric.
        \item If $(p,q)\in \{(4,5), (3,7)\}$, then $X$ admits a locally CAT(-1) metric.
    \end{enumerate}

ref_dict.cor: C(3) + T(6) implies CAT(0):
\begin{corollary}\label{cor: C(3) + T(6) implies CAT(0)}
    Let $\langle f:\Gamma\rightarrow \Theta\rangle$ be a $C(p)$-$T(q)$ graphical small cancellation presentation, then the associated non-thickened graphical complex $X$ can be endowed with a locally CAT(0) metric when $(p,q)=(3,6)$ and a locally $CAT(-1)$ metric when $(p,q)\in \{(3,7), (4,5)\}$.
\end{corollary}

ref_dict.thm: simplicial + T(6) implies CAT(0):
\begin{theorem}\label{thm: simplicial + T(6) implies CAT(0)}
    Let $G=\langle f: \Gamma \rightarrow \Theta\rangle$ be a $T(q)$ graphical small cancellation presentation with $Girth(\Gamma)\geq p$, where $Girth(\Gamma)$ denotes the length of a shortest cycle in $\Gamma$, and let $X$ be the non-thickened graphical complex associated to this presentation. 
    \begin{enumerate}[label=(\arabic*)]
        \item If $(p,q)=(3,6)$, then $X$ admits a locally CAT(0) metric.
        \item If $(p,q)\in \{(4,5), (3,7)\}$, then $X$ admits a locally CAT(-1) metric.
    \end{enumerate}
\end{theorem}

post_theorem_intro_text:
The proofs rely on the link condition for 2-dimensional complexes. We first show that small cancellation conditions provide lower bounds on the girth of the links in a graphical complex $X$. We then endow every 2-cell in $X$ with a Euclidean or hyperbolic metric and show that $X$ satisfies the link condition.

Note that any graphical presentation satisfying the assumptions of either statement of Theorem~\ref{thm: simplicial + T(6) implies CAT(0)} also satisfies the corresponding $C(p)$ small cancellation condition. 
If instead we start with the weaker assumption that a graphical presentation is $C(p)$-$T(q)$, then we can sightly modify the proof of Theorem~\ref{thm: simplicial + T(6) implies CAT(0)} so that the conclusions of the theorem still hold; see Corollary~\ref{cor: C(3) + T(6) implies CAT(0)}.

We now consider group actions on simply connected graphical complexes. Let $\widetilde{X}$ be a simply connected non-thickened graphical complex associated to a $C(p)$-$T(q)$ graphical presentation with $(p,q)\in\{(3,6),(4,5)\}$. Then it can be subdivided into a triangle complex $\widetilde{X}'$ (i.e., a 2-dimensional simplicial complex) and endowed with a piecewise Euclidean metric that is CAT(0), recurrent (in the sense of \cite[Definition 2.1]{OP21-recurrent}), and has rational angles (in the sense of \cite{NOP22-torsion}). 

Let $G$ be a group acting on $\widetilde{X}$ by automorphisms (see the definition in Section \ref{sec: prelimiaries}), then it also acts on $\widetilde{X}'$ by combinatorial automorphisms and by isometries with respect to the given metric. Therefore, either by the recurrent structure and \cite[Main Theorem]{OP21-recurrent} or by the CAT(0) structure and \cite[Theorem A]{OP22-Tits}, we obtain:  

\begin{corollary}\label{cor:Tits alternative}
    If the action is almost free (that is, there is a uniform bound on the cardinalities of all cell stabilizers), then $G$ satisfies the Tits alternative; more precisely, every finitely generated subgroup of $G$ is either virtually cyclic, virtually $\mathbb{Z}^2$, or contains a nonabelian free group. In particular, graphical $C(p)$-$T(q)$ small cancellation groups satisfy the Tits alternative for $(p,q)\in \{(3,6),(4,5)\}$.
\end{corollary}  

Additionally, since $\widetilde{X}'$ is a CAT(0) triangle complex with rational angles, applying \cite[Theorem 1.1]{NOP22-torsion}, we obtain the following, which proves a particular case of \cite[Meta-Conjecture, Conjecture]{HO-elliptic}:

\begin{corollary}\label{cor:fixed point}
    If $G$ is finitely generated and every element of $G$ fixes a cell in $\widetilde{X}$, then the entire group $G$ fixes a cell in $\widetilde{X}$. 
\end{corollary}

The paper is organized as follows. In Section \ref{sec: prelimiaries}, we recall the relevant definitions from graphical small cancellation theory; in Section \ref{sec: Small cancellation condition T}, we discuss several implications of the graphical small cancellation condition $T$, in particular how it bounds the girth of some links in a graphical complex; finally, in Section \ref{sec: Proof of the results}, we prove Theorem \ref{thm: simplicial + T(6) implies CAT(0)} and the corollaries.

