\begin{equation} \label{S}
S(f)=\sum_{i=1}^M{w_i\,f(\mathbf{x}_i)}\approx I(f)=\int_\Omega{f(\mathbf{x})\,d\mu}
\end{equation}
and
\begin{equation} \label{orth} 
\mathcal{G}_nf=\sum_{j=1}^{d_n}{c_j\,\phi_j}\;,\;\{c_j\}=G^{-1}\{S(f\phi_j)\}\;,\;\;G=(S(\phi_i\phi_j))_{1\leq i,j\leq d_n}\;.
\end{equation}
where $f\in C(\Omega)$ and the cubature rule satisfies the MZ property
\begin{equation} \label{MZD}
A \|p\|_{L^2}^2 \leq S(p^2)  \leq B \|p\|_{L^2}^2, \quad  \forall p \in {\mathbb{P}}_n\;,\;\;\|p\|_{L^2}^2=I(p^2)\;.
\end{equation}
with
\begin{equation} \label{eta}
\eta=\eta(n)=\max\{|A-1|,|B-1|\}<1 
\end{equation}
Then, to prove the main theorem, the following bound holds 
\begin{equation} \label{alt}
\|f-\mathcal{G}_nf\|_{L^2} 
\leq \left(1+\sqrt{\mbox{cond}_2(G)}\,\right) \sqrt{\mu(\Omega)} \,E_n(f)
\leq \left(1+\sqrt{\frac{1+\eta}{1-\eta}}\right)\,\sqrt{\mu(\Omega)}\;E_n(f)\;,
\end{equation}
which, in case the cubature rule is exact on the constants, can be refined to
\begin{equation} \label{err-Gn}
\|f-\mathcal{G}_nf\|_{L^2}\leq 
\left(1+\frac{1}{\sqrt{A}}\,\right)\,\sqrt{\mu(\Omega)}\,E_n(f)\leq 
\left(1+\frac{1}{\sqrt{1-\eta}}\right)\,\sqrt{\mu(\Omega)}\;E_n(f)\;.
\end{equation}

