\begin{lemma}\emph{(}\cite[Lemma 4.1 and Example 4.5]{CLZ23}\emph{)}\label{lem:finitet=t0}
Let $\mathbbm{t}_1 = (\mathcal{K}_1^{\leq 0}, \mathcal{K}1^{\geq 0})$ be a bounded $t$-structure on a triangulated category $\mathcal{K}$, whose heart $\mathcal{H}_{\mathbbm{t}_1}$ is a locally finite abelian category with finitely many isomorphism classes of simple objects. Then for any bounded t-structure $\mathbbm{t}_2=(\mathcal{K}^{\leq 0}_2, \mathcal{K}^{\geq 0}_2)$ on $\mathcal{K}$, there are integers $m\leq n$ such that $\mathcal{K}^{\leq m}_1\subseteq \mathcal{K}^{\leq 0}_2 \subseteq \mathcal{K}^{\leq n}_1$ and $\mathcal{K}^{\geq n}_1\subseteq \mathcal{K}^{\geq 0}_2 \subseteq \mathcal{K}^{\geq m}_1$.
\end{lemma}

ref_dict.coro:triangulatedfaithful:
\begin{corollary}\label{coro:triangulatedfaithful}
Let $\mathcal{C}$ be a multiring category and $\mathcal{M}$ be a left faithful $\mathcal{C}$-module category. Then $\mathbf{D}^b(\mathcal{M})$ is a faithful triangulated module category over $\mathbf{D}^b(\mathcal{C})$. In particular, for a tensor category $\mathcal{C}$ and any $\mathcal{C}$-module category $\mathcal{M}$, the bounded derived category $\mathbf{D}^b(\mathcal{M})$ is faithful over $\mathbf{D}^b(\mathcal{C})$.
\end{corollary}

