  \end{equation*}
  Furthermore, for \(q_N\) as in Theorem~\ref{main_thm}, it also holds
  that
  \begin{equation*}
    q_{N_0} > q_{N_0+1} > \dots > q_N > q_{N+1} > \dots > 1 \, .
  \end{equation*}
\end{proposition}

\begin{proposition}
  \label{prop:N_small}
  For \(N_{0} = \codenumber{64}\) we have
  \begin{equation*}
    \lambda_{1}(\mathcal{P}_3) > \lambda_{1}(\mathcal{P}_4) >
    \dots > \lambda_1(\mathcal{P}_N) > \lambda_1(\mathcal{P}_{N+1}) >
    \dots > \lambda_{1}(\mathcal{P}_{N_{0} - 1}) > \lambda_{1}(\mathcal{P}_{N_{0}}).
