\end{equation*}
with $n$ and $c$ remaining positive in $\bar{\Omega} \times (0, \infty)$. Moreover, there exists a constant $C > 0$ such that
\begin{align} \label{thm2-1}
    \| n(\cdot,t) \|_{L^\infty(\Omega)} + \| c(\cdot,t) \|_{W^{1,\infty}(\Omega)} + \| u(\cdot,t) \|_{L^\infty(\Omega)} \leq C \quad \text{for all } t > 0.
\end{align}

\end{theorem}

