\item Section \ref{section key LES}: establish “the key exact sequence mentioned in (2) above.”
\item Section \ref{section main result}: use the results of Section \ref{section key LES} together with “an argument circumventing the use of results from \cite{Choudhury-Hogadi}” to prove \cite[Lemma 5.1]{BHS} (see Lemma \ref{lemma isogeny}), which in turn completes the proof of Theorem \ref{thm intro main}.
\end{itemize}

