\begin{lemma} \label{abs. con. of law of u_n}
For any $(x,t)\in D\times(0,T]$, the law of the random variable $u_{n}(x,t)$ is absolutely
continuous with respect to the Lebesgue measure on $\mR$.
\end{lemma}
Finally show “this property of the law of $u_{n}(x,t)$ translates to the analogous property for the law of $u(x,t)$,” i.e.:
\begin{theorem} \label{main theorem 2}
For any $(x,t)\in D\times(0,T]$, the law of the random variable $u(x,t)$ is absolutely continuous with respect to the Lebesgue measure on $\mR$.
\end{theorem}
which in turn implies the existence of a density for $u(x,t)$.

expanded_theorem:
Let $u$ be the unique solution of
\begin{equation} \label{stoch. model}
\nu_{t} = - \big{(} u_{xx} - f(u) \big{)}_{xx} + \sigma \dot{W}_H\quad \text{in}\ D\times(0,T].
\end{equation}
subjected to the homogeneous Neumann boundary conditions
\begin{equation} \label{Neumann b.c.}
\dfrac{\partial u}{\partial x} = \dfrac{\partial^{3} u}{\partial x^{3}} = 0\quad \text{on}\ \{0,\pi\}\times[0,T].
\end{equation}
and with a deterministic initial condition $u_{0} \in C(D)$. Then, the Malliavin derivative of $u(x,t)$ exists locally. Furthermore, for any $(x,t) \in D \times (0,T]$, the law of the random variable $u(x,t)$ is absolutely continuous with respect to the Lebesgue measure on $\mathbb{R}$.

ref_dict.thm:main:
\begin{theorem}\label{thm:main}
Let $n(B)$ be the number of triples $u,v,w\in\N$ of square-full integers, such that $u+v=w$ and
$w\le B$. Then
\[n(B)\ll_\ep B^{3/5-3/1555+\ep}\]
for any fixed $\ep>0$.
\end{theorem}

GPS.justification:
Some reasoning is required about how 
) dependence of implied constants on ε works, and 
b) which exponent statements are weaker/stronger (e.g., why C is weaker than A, why D is too strong). However, without prior knowledge of the specific exponent improvement −3/1555, the choice is not generatively derivable.

ref_dict.prop:van:
\begin{proposition}\label{prop:van}
    Let $W$ be the Weyl group of a complex semisimple Lie group and $u,v \in W$. Then the mixed Hodge spaces $H^{1,(0,0)}(\cR_{u,v};\mathbb{C})$ and $H^{2,(1,1)}(\cR_{u,v};\mathbb{C})$ vanish.
\end{proposition}

ref_dict.thm:gj:
\begin{theorem}
\label{thm:gj}
Let $u \leq v$ be elements of the Weyl group $W$ of a complex semisimple Lie algebra $\mathfrak g$. Then 
\[
\dim \Ext_{\mathcal{O}}^{\ell(u,v)-1}(M_u,M_v)=d_{u,v}. 
\]
Consequently, $\dim \Ext_{\mathcal{O}}^{\ell(u,v)-1}(M_u,M_v)$ is a combinatorial invariant of the poset $[u,v]$.
\end{theorem}

ref_dict.conj:cic:
\begin{conjecture}[Combinatorial Invariance Conjecture]
\label{conj:cic}
Let $[u,v] \subset W$ and $[u',v'] \subset W'$ be Bruhat intervals such that $[u,v] \cong [u',v']$ as posets. Then $P_{u,v}(q)=P_{u',v'}(q)$.
\end{conjecture}

ref_dict.thm:d-equals-g:
\begin{theorem}
\label{thm:d-equals-g}
Let $u \leq v$ be elements of any Coxeter group $W$. Then $d_{u,v}=g_{u,v}$. 
\end{theorem}

post_theorem_intro_text:
\Cref{thm:d-equals-g} was proven by Patimo \cite{Patimo-q-coefficient} in the case where $W$ is finite and simply-laced. His argument relied on the \emph{generalized lifting property} \cite{Tsukerman-Williams} which is known \cite{caselli-sentinelli-gen-lifting} to hold only in this case. Our proof in \Cref{sec:proof} introduces new techniques using divergences of increasing paths to circumvent this.

\begin{corollary}
\label{cor:cic-for-coefficients}
Let $u \leq v \in W$ and $u' \leq v' \in W'$ be such that $[u,v] \cong [u',v']$. Then $[q]P_{u,v}=[q]P_{u',v'}$, $[q]R_{u,v}=[q]R_{u',v'}$, $[q^{\ell(u,v)-1}]R_{u,v}=[q^{\ell(u',v')-1}]R_{u',v'}$, and $[q^{\ell(u,v)}-2]\tR_{u,v}=[q^{\ell(u',v')}-2]\tR_{u',v'}$.
\end{corollary}

Although $P_{u,v}$ can have a quadratic term when $5 \leq \ell(u,v)\leq 6$, we are nevertheless able to prove \Cref{conj:cic} for such intervals.

\begin{corollary}
\label{cor:cic-length-5-6}
Let $u \leq v$ be elements of any Coxeter group $W$ and suppose $\ell(u,v) \leq 6$. Let $u' \leq v'$ be elements of a Coxeter group $W'$ such that $[u,v] \cong [u',v']$. Then $P_{u,v}=P_{u',v'}$, $R_{u,v}=R_{u',v'}$, and $\tR_{u,v}=\tR_{u',v'}$. 
\end{corollary}

