\begin{proof}
By \cref{f:polychar},
each polyhedral cone $C\in\mathcal{C}$ has finitely many faces, i.e., 
$\mathcal{F}(C)$ is finite. 
Because $\mathcal{C}$ is finite, so is 
$\mathcal{F} := \bigcup_{C\in\mathcal{C}} \mathcal{F}(C)$
and also 
$\{\spn(F)\}_{F\in\mathcal{F}}$. 
Now suppose that $\mathcal{L} = \{\spn(F)\}_{F\in\mathcal{F}}$.
If $x\in X$ and $C\in\mathcal{C}$, then 
\cref{c:projandfacecone} 
yields $P_Cx = P_Lx$, for some $L\in\mathcal{L}$ depending 
on $C$ and $x$. 
It follows that the sequence $(x^{(n)})_\nnn$ can be viewed 
as being generated by $\mathcal{L}$. Since $X$ is finite-dimensional, we obtain that $\mathcal{L}$ is obviously innately regular (because all linear subspace
are automatically closed). 
Therefore, the result follows from \cref{f:GT}.
\end{proof}

\section{General extension to polyhedral cones}

\label{s:infdim} 

In this section, we return to our general assumption on $X$, i.e., 
\begin{empheq}[box=\mybluebox]{equation}
\text{
$X$ is finite or infinite-dimensional. 
}
\end{empheq}

The following representation result for a convex polyhedral set and 
its projection is useful (see \cite[Theorem~3.3.16]{HBthesis}): 

\begin{fact}
\label{f:thesis}
Let $C$ be a nonempty polyhedral subset of $X$, represented 
as 
\begin{equation}
C = \menge{x\in X}{(\forall i\in I)\;\;\scal{a_i}{x}\leq \beta_i}, 
\end{equation}
where $I$ is a finite index set, each $a_i$ belongs to 
$X\smallsetminus\{0\}$ and each $\beta_i$ is a real number.
Let $K$ be a closed linear subspace of $\bigcap_{i\in I}\ker a_i$, 
and set $D := C\cap K^\perp$. 
Then $D$ is a nonempty polyhedral subset of $K^\perp$ and 
\begin{equation}
\label{e:thesis}
P_C = P_K + P_DP_{K^\perp}. 
\end{equation}
Note that if $K = \bigcap_{i\in I}\ker a_i$, 
then $K^\perp$ is finite-dimensional. 
\end{fact}

We are now ready to extend \cref{t:GTpolycone} to
general Hilbert spaces: 

\begin{theorem}[main result]
\label{t:GTpolyconeinfi} 
Let $\mathcal{C}$ be a nonempty finite collection of 
nonempty polyhedral cones in $X$. 
Let $\lambda\in]0,1]$ and $x^{(0)}\in X$.
Generate a sequence $(x^{(n)})_{\nnn}$ in $X$ as follows:
Given a current term $x^{(n)}$, pick $R_n \in \mathcal{R}_{\mathcal{C},[\lambda,2-\lambda]}$, and update via
\begin{equation}
  x^{(n+1)} := R_n x^{(n)}.
\end{equation}
Then 
\begin{equation}
\sum_{n=0}^\infty \norm{x^{(n+1)}-x^{(n)}}^\gamma <+\infty\quad \text{for all $\gamma>0$.}
\end{equation}
\end{theorem}
\begin{proof}
For each $C\in\mathcal{C}$, we pick
a finite-codimensional closed 
linear subspace $K_C$ of $X$ as in 
\cref{f:thesis}. 
Next, we set $K := \bigcap_{C\in\mathcal{C}} K_C$.
Then $K$ is a closed linear subspace of $X$, still 
finite-codimensional. 
By \cref{f:thesis} again, we have 
\begin{equation}
\label{e:boom}
(\forall C\in\mathcal{C})\quad
P_C = P_K + P_{D_C}P_{K^\perp},
\end{equation}
where $D_C = C \cap K^\perp$ is a nonempty polyhedral subset of 
the finite-dimensional space $K^\perp$. Note that $D_C$ is also a polyhedral cone because the intersection of a polyhedral cone and a finite-codimensional linear subspace is still polyhedral. 

The starting point $x_0$ is decomposed as 
$x^{(0)} = k^{(0)} + y^{(0)}$, where 
$k^{(0)} := P_Kx^{(0)} \in K$ and $y^{(0)} := P_{K^\perp}x^{(0)} \in K^\perp$. 
Observe that \cref{e:boom} implies that 
$(x^{(n)})_\nnn = (k^{(0)})_\nnn +(y^{(n)})_\nnn$, 
where $(y^{(n)})_\nnn$  
is generated using the finite collection of polyhedral cones 
$\{D_C\}_{C\in\mathcal{C}}$ in the finite-dimensional space $K^\perp$. Observe that
\begin{equation}
    \left(\forall n\in\mathbb{N}\right)\quad \norm{x^{(n+1)}-x^{(n)}}=\norm{y^{(n+1)}-y^{(n)}}.
\end{equation}
The result then follows from \cref{t:GTpolycone}.
\end{proof}

